INSERT INTO `scale` (`id`,`code`,`name`,`full_name`,`version`,`summary`,`instruction`,`scoring_type`,`score_min`,`score_max`,`remark`) VALUES (4,'MMSE','简明精神状态检查','Mini-Mental State Examination (MMSE)','1.0','Folstein 1975 年创立，最常用的认知及智能检查量表，共 30 个条目、30 分。','对患者进行定向、记忆、注意与计算、语言、视空间等 11 个认知域的检查，每题回答正确得 1 分。节点分数：17 分（文盲）、20 分（1-6 年）、24 分（>6 年）。','ITEMIZED',0.0,30.0,'得分 ≤ 对应教育程度界值判为异常（认知障碍筛查阳性）。');
