INSERT INTO `scale` (`id`,`code`,`name`,`full_name`,`version`,`summary`,`instruction`,`scoring_type`,`score_min`,`score_max`,`remark`) VALUES (5,'MOCA_B','蒙特利尔认知评估基础量表（中文版）','Montreal Cognitive Assessment - Basic (MoCA-B)','1.0','Nasreddine 等 2004 年编制、2014 年推出基础版，用于快速筛查 MCI，适用于文盲与低教育老人，满分 30 分。','涵盖执行功能、词语流畅性、定向、计算、抽象、延迟回忆、视知觉、命名、注意等认知域。节点（异常值指小于等于节点）：文盲/小学 19 分、中学 22 分、大学 24 分。','ITEMIZED',0.0,30.0,'抽象题「橘子香蕉」为练习、不计分；即刻回忆不计分。');
