INSERT INTO `scale` (`id`,`code`,`name`,`full_name`,`version`,`summary`,`instruction`,`scoring_type`,`score_min`,`score_max`,`remark`) VALUES (6,'CDR','临床痴呆评定量表','Clinical Dementia Rating (CDR)','1.0','对 6 个功能域（记忆力、定向力、判断与解决问题、社会事务、家务与业余爱好、个人自理）分别评定，综合得出整体 CDR 评分与 CDR-SB。','分别对知情者和受试者本人进行访谈。只有当能力的减退是由认知障碍引起时才计分。6 个功能域各记 0 / 0.5 / 1 / 2 / 3 分；以记忆力为主要项目、其余 5 项为次要项目，按 Morris 规则综合出整体 CDR；CDR-SB = 6 域得分之和。','CDR',0.0,3.0,'CDR 整体评分与 CDR-SB 由算法计算，详见 scoring/scales/cdr.py。');
